(async function(){
  const params=new URLSearchParams(location.search),short=params.get('mode')==='shortlist',repair=params.get('mode')==='repair',ticket=params.get('mode')==='ticket',wide=params.get('mode')==='wide',marker=params.get('mode')==='marker',neutral=params.has('neutral'),overview=params.has('overview'),name=marker?'marker-selection.json':wide?'wide-selection.json':ticket?'ticket-selection.json':repair?'repair-selection.json':short?'shortlist.json':'final-selection.json',data=await(await fetch('../../openspec/changes/expand-feature-research/evidence/'+name)).json(),F=window.SpaceFoxF,R=window.SpaceFoxFR;
  if(overview)document.body.classList.add('overview');
  const original=data.candidates,legacy=window.SpaceFoxFeatureData.legacy.controls.map(x=>({id:x.id,legacy:x.id,parents:[],stage:'legacy'})),pool=short?[...original,...legacy]:original,perm=short?[12,5,1,8,14,3,10,0,7,13,11,2,9,6,4]:pool.map((_,i)=>i),items=perm.map((n,i)=>({candidate:pool[n],letter:String.fromCharCode(65+i)}));
  const label=displayLabel=>({full:displayLabel,displayLabel}),hero={id:'presentation-only',language:'ru',status:'both',clock:'18:38',flags:{timeKnown:true,rescheduled:true,stale:true},fixture:{rocket:label('Falcon 9'),operator:label('SpaceX'),purpose:label('Навигационные спутники'),site:label('США · Канаверал'),point:[-80.6,28.6],model:'falcon'},countdown:{seconds:9240,displayLabel:'T−2ч 34м'},fields:[{role:'steps',value:6842,displayLabel:'6 842'},{role:'energy',value:68,displayLabel:'68'},{role:'heart',value:72,displayLabel:'72'},{role:'battery',value:82,displayLabel:'82%'}]},scenes=[hero,...data.demoScenes];
  const page=document.querySelector('#page'),scene=document.querySelector('#scene'),size=overview?5:3;
  for(let i=0;i<Math.ceil(items.length/size);i++){const o=document.createElement('option');o.value=i;o.textContent=items.slice(i*size,(i+1)*size).map(x=>x.letter).join(' · ');page.append(o);}
  scenes.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=i===0?'Короткая миссия · RU':`${i} · ${s.language} · ${s.fixture.rocket.displayLabel} · ${s.status}`;scene.append(o);});
  function paint(){const shown=items.slice(Number(page.value)*size,(Number(page.value)+1)*size),s=scenes[Number(scene.value)],g=document.querySelector('#gallery');g.replaceChildren();for(const item of shown){const card=document.createElement('article');card.className='card';const h=document.createElement('h2');h.textContent=neutral?item.letter:(data.names?.[item.candidate.id]||item.candidate.id);const p=document.createElement('div');p.className='preview';p.append(R.render(item.candidate,s));const canvas=R.aod(item.candidate,s);canvas.dataset.candidate=item.candidate.id;card.append(h,p,canvas);g.append(card);}}
  page.onchange=paint;scene.onchange=paint;document.querySelector('#animate').onclick=()=>{for(const face of document.querySelectorAll('.face')){face.classList.remove('launch-demo');void face.offsetWidth;face.classList.add('launch-demo');}};
  document.querySelector('#aodExport').onclick=()=>{const raw=document.querySelector('#raw');raw.style.display='block';raw.value=JSON.stringify([...document.querySelectorAll('.card canvas')].map(canvas=>({candidate:canvas.dataset.candidate,clock:scenes[Number(scene.value)].clock,countdown:scenes[Number(scene.value)].countdown.displayLabel,pixels:JSON.parse(canvas.dataset.pixels),png:canvas.toDataURL('image/png')})));};
  await Promise.all([...new Set(Object.values(F.fonts))].map(f=>document.fonts.load(`600 80px '${f}'`)));await document.fonts.load("500 21px 'Noto Sans'",'Россия USA');await document.fonts.ready;paint();
})();
